use serde_json::{json,Value};
use ss_core::{java_runtime::{Rc,RefCell,Date,withClock},cn::wps::moss::{app::{KmoBook::KmoBook,KmoBookApi::KmoBookApi},core::book::KmoAppSettings::KmoAppSettings,xlsxw::docProps::{XlsxwApp::XlsxwApp,XlsxwCore::XlsxwCore,XlsxwCustom::XlsxwCustom}}};
use io_poi_compact::org::apache::poi::hpsf::Property::{Property,PropertyValue};
use kfc_kfc_alpha::kfc::ooxfw::OxfwPackage::OxfwPackage;
use util::cn::wps::moffice::util::UUIDUtil::withEntropy;
use util_adapter::cn::wps::core::runtime::Platform::Platform;
use std::io::{Cursor,Read};
fn property(p:&Property)->Value{let mut out=json!({"id":p.getID(),"type":p.getType()});match p.getValue(){PropertyValue::Date(v)=>out["date"]=json!(v.getTime()),PropertyValue::Str(v)=>out["value"]=json!(v),PropertyValue::Bool(v)=>out["value"]=json!(v),PropertyValue::Int(v)=>out["value"]=json!(v),PropertyValue::None=>out["value"]=Value::Null,_=>panic!("unobserved value")};out}
fn strings(s:&mut KmoAppSettings,values:&[Option<&str>]){s.setAppName(values[0].map(str::to_owned));s.setAppVersion(values[1].map(str::to_owned));s.setHyperlinkBase(values[2].map(str::to_owned));s.setManager(values[3].map(str::to_owned));s.setCompany(values[4].map(str::to_owned));s.setCreator(values[5].map(str::to_owned));s.setLastModifiedBy(values[6].map(str::to_owned));s.setTitle(values[7].map(str::to_owned));s.setKeywords(values[8].map(str::to_owned));s.setCategory(values[9].map(str::to_owned));s.setDescription(values[10].map(str::to_owned));s.setContentStatus(values[11].map(str::to_owned));s.setContentType(values[12].map(str::to_owned));s.setSubject(values[13].map(str::to_owned));}
fn snapshot(s:&KmoAppSettings,book:&KmoBook)->Value{let props:Vec<_>=s.getCustomProps().borrow().entrySet().map(|(key,p)|json!({"key":key,"property":p.as_deref().map(property)})).collect();json!({"AppName":s.getAppName(),"AppVersion":s.getAppVersion(),"HyperlinkBase":s.getHyperlinkBase(),"Manager":s.getManager(),"Company":s.getCompany(),"Creator":s.getCreator(),"LastModifiedBy":s.getLastModifiedBy(),"Title":s.getTitle(),"Keywords":s.getKeywords(),"Category":s.getCategory(),"Description":s.getDescription(),"ContentStatus":s.getContentStatus(),"ContentType":s.getContentType(),"Subject":s.getSubject(),"Scale":s.getScale(),"LinkDirty":s.getLinkDirty(),"Security":s.getSecurity(),"Created":s.getCreated().map(|d|d.getTime()),"Modified":s.getModified().map(|d|d.getTime()),"reading":s.getReadingLayout(),"silent":book.isSilentSaveWithoutDirty(),"dirty":book.isDirty(),"props":props})}
fn history(book:&Rc<KmoBook>,expected:&Value)->Value{
    let mut s=KmoAppSettings::KmoAppSettings(book.clone());book.setDirty(false);book.setSilentSaveWithoutDirty(false);let mut out=vec![json!({"step":"default","value":snapshot(&s,book),"bookSame":Rc::ptr_eq(&book.getAppSettings(),&book.getAppSettings())})];
    for mode in 0..3{strings(&mut s,&[match mode{0=>None,1=>Some(""),_=>Some("<&>'\"\n\0中文😀")};14]);s.setScale(mode%2==0);s.setLinkDirty(mode%2!=0);s.setSecurity(match mode{0=>-1,1=>i32::MIN,_=>i32::MAX});out.push(json!({"step":format!("strings{mode}"),"value":snapshot(&s,book)}));}
    let bytes=Rc::new(RefCell::new(vec![0,1,255]));s.setHyperlinkBaseXls(Some(bytes.clone()));bytes.borrow_mut()[0]=9;out.push(json!({"step":"bytes","same":Rc::ptr_eq(&bytes,&s.getHyperlinkBaseXls().unwrap()),"value":base64(&s.getHyperlinkBaseXls().unwrap().borrow())}));s.setHyperlinkBaseXls(None);
    let date=Rc::new(Date::fromTime(0));s.setCreated(Some(date.clone()));s.setModified(Some(date.clone()));date.setTime(-123456789);out.push(json!({"step":"dateAlias","same":Rc::ptr_eq(&s.getCreated().unwrap(),&date)&&Rc::ptr_eq(&s.getModified().unwrap(),&date),"value":snapshot(&s,book)}));
    s.setReadingLayout(true);out.push(json!({"step":"readingTrue","value":snapshot(&s,book)}));s.setReadingLayout(false);out.push(json!({"step":"readingFalse","value":snapshot(&s,book)}));
    let mut previous:Option<Rc<Property>>=None;
    for action in ["createNew","updateSuffix","updateFalse","updateTrue","addNull","addEmpty","createNew","createNew","updateTrue","updateTrue"]{match action{"createNew"=>s.createIcvFromNew(),"updateSuffix"=>s.updateIcv__suffix(Some("ZZ")),"updateFalse"=>s.updateIcv(false),"updateTrue"=>s.updateIcv(true),"addNull"=>s.addIcv(),_=>s.addIcv__suffix(Some(""))};let current=s.getIcv();let same=match(&current,&previous){(Some(a),Some(b))=>Rc::ptr_eq(a,b),(None,None)=>true,_=>false};out.push(json!({"step":action,"same":same,"has":s.hasIcv(),"value":snapshot(&s,book)}));previous=current;}
    s.getCustomProps().borrow_mut().put("KSOTemplateUUID".into(),Some(Rc::new(Property::new(4,31,PropertyValue::Str("template".into())))));out.push(json!({"step":"template","same":Rc::ptr_eq(&s.getTemplateIcv().unwrap(),s.getCustomProps().borrow().get("KSOTemplateUUID").unwrap().as_ref().unwrap())}));
    let rows=expected.as_array().unwrap();let clock=Rc::new(RefCell::new(std::collections::VecDeque::from([rows[rows.len()-2]["value"]["Created"].as_i64().unwrap(),rows[rows.len()-2]["value"]["Modified"].as_i64().unwrap(),rows[rows.len()-1]["value"]["Modified"].as_i64().unwrap()])));let input=clock.clone();
    withClock(move||input.borrow_mut().pop_front().expect("extra clock input"),||{s.setCreated(None);s.setModified(None);s.updateSettings();let first=s.getCreated().unwrap();let modified=s.getModified().unwrap();out.push(json!({"step":"updateSettings1","value":snapshot(&s,book)}));s.updateSettings();out.push(json!({"step":"updateSettings2","createdSame":Rc::ptr_eq(&first,&s.getCreated().unwrap()),"modifiedSame":Rc::ptr_eq(&modified,&s.getModified().unwrap()),"value":snapshot(&s,book)}));});assert!(clock.borrow().is_empty());json!(out)
}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn entries(file:&std::path::Path)->Value{let mut zip=zip::ZipArchive::new(Cursor::new(std::fs::read(file).unwrap())).unwrap();let mut out=vec![];for i in 0..zip.len(){let mut entry=zip.by_index(i).unwrap();let mut bytes=vec![];entry.read_to_end(&mut bytes).unwrap();out.push(json!({"name":entry.name(),"method":entry.compression().to_u16(),"size":entry.size(),"crc":entry.crc32(),"bytes":base64(&bytes)}));}json!(out)}
fn packages(book:&Rc<KmoBook>,path:&std::path::Path)->Value{let mut out=vec![];let choices=[None,Some(""),Some("文档<&>'\"\n\r\0😀")];for mask in 0..24{let mut s=KmoAppSettings::KmoAppSettings(book.clone());let values:Vec<_>=(0..14).map(|i|choices[(i+mask)%3]).collect();strings(&mut s,&values);s.setScale(mask&1!=0);s.setLinkDirty(mask&2!=0);s.setSecurity(match mask%3{0=>-1,1=>0,_=>i32::MIN});Platform::setUserName(choices[mask%3]);let date=Rc::new(Date::fromTime(1735689600000+mask as i64*1000));if mask&4!=0{s.setCreated(Some(date.clone()));}if mask&8!=0{s.setModified(Some(date.clone()));}if mask&16!=0{s.getCustomProps().borrow_mut().put("ICV".into(),Some(Rc::new(Property::new(-1,31,PropertyValue::Str("fixed-icv".into())))));}for i in 0..32{let key=(0..5).map(|bit|if i&(1<<bit)==0{"Aa"}else{"BB"}).collect::<String>();let (kind,value)=match i%6{0=>(11,PropertyValue::Bool(i&1==0)),1=>(31,PropertyValue::Str(format!("s<&>\n\0{i}"))),2=>(3,PropertyValue::Int(i32::MIN+i)),3=>(64,PropertyValue::Date(date.clone())),4=>(999,PropertyValue::Str("skipped".into())),_=>(30,PropertyValue::Str("".into()))};s.getCustomProps().borrow_mut().put(key,Some(Rc::new(Property::new(i as i64,kind,value))));}let file=path.join(format!("rust-{mask}.zip"));let mut pack=OxfwPackage::OxfwPackage(file.to_str().unwrap()).unwrap();XlsxwApp::write(&mut pack.getAppPart().borrow_mut(),&s);XlsxwCore::write(&mut pack.getCorePart().borrow_mut(),&s);date.setTime(-2208988800000+mask as i64*1000);XlsxwCustom::write(&mut pack.getCustomPart().borrow_mut(),&mut s);pack.close().unwrap();out.push(json!({"mask":mask,"entries":entries(&file),"icv":s.getIcv().as_deref().map(property)}));}json!(out)}
#[test]
fn original_android_settings_history_and_docprops_packages(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/docprops-r0b32");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();ss_core::java_runtime::KfsZip::install();let entropy:std::collections::VecDeque<[u8;16]>=java["entropy"].as_array().unwrap().iter().map(|v|{let s=v.as_str().unwrap();std::array::from_fn(|i|u8::from_str_radix(&s[i*2..i*2+2],16).unwrap())}).collect();let entropy=Rc::new(RefCell::new(entropy));let input=entropy.clone();withEntropy(move||input.borrow_mut().pop_front().expect("extra entropy input"),||{let history=history(&book,&java["history"]);std::fs::write(p.join("rust-history.json"),serde_json::to_vec_pretty(&history).unwrap()).unwrap();assert_eq!(history,java["history"]);let packages=packages(&book,&p.join("zips"));std::fs::write(p.join("rust-packages.json"),serde_json::to_vec_pretty(&packages).unwrap()).unwrap();assert_eq!(packages,java["packages"]);});assert!(entropy.borrow().is_empty(),"unused entropy input");}
